<?php
declare(strict_types=1); namespace TmsAi\Services; use TmsAi\Core\App;
final class UsageService { public function record(array $e):void{$s=App::db()->prepare('INSERT INTO usage_events(request_id,provider_id,client_key_id,model,upstream_model,input_tokens,output_tokens,total_tokens,usage_source,status_code,latency_ms,success,created_at) VALUES(:r,:p,:c,:m,:u,:i,:o,:tt,:s,:sc,:l,:ok,:t)');$v=[':r'=>(string)($e['request_id']??''),':p'=>(int)($e['provider_id']??0),':c'=>(int)($e['client_key_id']??0),':m'=>(string)($e['model']??''),':u'=>(string)($e['upstream_model']??''),':i'=>(int)($e['input_tokens']??0),':o'=>(int)($e['output_tokens']??0),':tt'=>(int)($e['total_tokens']??0),':s'=>(string)($e['usage_source']??'provider'),':sc'=>(int)($e['status_code']??0),':l'=>(int)($e['latency_ms']??0),':ok'=>!empty($e['success'])?1:0,':t'=>time()];foreach($v as$k=>$x)$s->bindValue($k,$x,is_int($x)?SQLITE3_INTEGER:SQLITE3_TEXT);$s->execute();}
public function summary():array{$start=strtotime('today');$row=App::db()->querySingle('SELECT COUNT(*) requests,COALESCE(SUM(input_tokens),0) input_tokens,COALESCE(SUM(output_tokens),0) output_tokens,COALESCE(SUM(total_tokens),0) total_tokens,COALESCE(SUM(success),0) success FROM usage_events WHERE created_at>='.(int)$start,true)?:[];$ps=[];$r=App::db()->query('SELECT p.id,p.name,COUNT(u.id) requests,COALESCE(SUM(u.total_tokens),0) total_tokens,COALESCE(SUM(u.input_tokens),0) input_tokens,COALESCE(SUM(u.output_tokens),0) output_tokens,COALESCE(AVG(CASE WHEN u.success=1 THEN u.latency_ms END),0) avg_latency FROM providers p LEFT JOIN usage_events u ON u.provider_id=p.id AND u.created_at>='.(int)$start.' GROUP BY p.id ORDER BY p.priority,p.id');while($p=$r->fetchArray(SQLITE3_ASSOC)){$p['quotas']=$this->quotaStatus((int)$p['id']);$ps[]=$p;}$row['success_rate']=((int)($row['requests']??0))>0?round(((int)($row['success']??0))*100/(int)$row['requests'],1):100.0;$row['providers']=$ps;$row['server_time']=time();return$row;}
public function quotaStatus(int $pid):array{$now=time();$s=App::db()->prepare('SELECT * FROM quota_windows WHERE provider_id=:p AND enabled=1 ORDER BY window_seconds');$s->bindValue(':p',$pid,SQLITE3_INTEGER);$r=$s->execute();$o=[];while($q=$r?->fetchArray(SQLITE3_ASSOC)){$w=max(60,(int)$q['window_seconds']);if($q['reset_mode']==='fixed'){$a=(int)$q['reset_anchor'];if($a<=0)$a=strtotime('today');$cycles=intdiv(max(0,$now-$a),$w);$start=$a+$cycles*$w;$reset=$start+$w;}else{$start=$now-$w;$reset=$now+$w;$first=App::db()->querySingle('SELECT MIN(created_at) FROM usage_events WHERE provider_id='.$pid.' AND created_at>='.$start);if($first)$reset=(int)$first+$w;}$u=App::db()->querySingle('SELECT COUNT(*) requests,COALESCE(SUM(total_tokens),0) tokens FROM usage_events WHERE provider_id='.$pid.' AND created_at>='.(int)$start,true)?:['requests'=>0,'tokens'=>0];$tl=(int)$q['token_limit'];$rl=(int)$q['request_limit'];$tp=$tl>0?min(100,round((int)$u['tokens']*100/$tl,1)):0;$rp=$rl>0?min(100,round((int)$u['requests']*100/$rl,1)):0;$o[]=['id'=>(int)$q['id'],'label'=>$q['label'],'window_seconds'=>$w,'tokens_used'=>(int)$u['tokens'],'token_limit'=>$tl,'requests_used'=>(int)$u['requests'],'request_limit'=>$rl,'percent'=>max($tp,$rp),'reset_at'=>$reset,'remaining_seconds'=>max(0,$reset-$now)];}return$o;}
public function providerAllowed(int $pid):bool{foreach($this->quotaStatus($pid)as$q)if(($q['token_limit']>0&&$q['tokens_used']>=$q['token_limit'])||($q['request_limit']>0&&$q['requests_used']>=$q['request_limit']))return false;return true;}}
